This is the classic Exercism food-chain exercise. Let's implement it.

Verse structure:
- Verse 1: fly — no comment line, no "swallowed X to catch Y" chain, just the intro + the final "I don't know why..."
- Verse 2: spider — comment "It wriggled and jiggled and tickled inside her." followed by "She swallowed the spider to catch the fly." followed by the final line.
- Verse 3: bird — comment "How absurd to swallow a bird!" followed by "She swallowed the bird to catch the spider that wriggled and jiggled and tickled inside her." followed by "She swallowed the spider to catch the fly." followed by the final line.
- ...
- Verse 8: horse — "She's dead, of course!"

Note that when referring to the spider in the chain, it's "the spider that wriggled and jiggled and tickled inside her."

Implementation:

```go
package foodchain

import "strings"

var animals = []struct {
	name    string
	comment string
}{
	{"fly", ""},
	{"spider", "It wriggled and jiggled and tickled inside her."},
	{"bird", "How absurd to swallow a bird!"},
	{"cat", "Imagine that, to swallow a cat!"},
	{"dog", "What a hog, to swallow a dog!"},
	{"goat", "Just opened her throat and swallowed a goat!"},
	{"cow", "I don't know how she swallowed a cow!"},
	{"horse", "She's dead, of course!"},
}

func Verse(v int) string {
	var b strings.Builder
	a := animals[v-1]
	b.WriteString("I know an old lady who swallowed a " + a.name + ".\n")
	b.WriteString(a.comment + "\n")
	if v < 8 {
		for i := v - 1; i >= 1; i-- {
			prev := animals[i]
			if prev.name == "spider" {
				b.WriteString("She swallowed the " + a.name + " to catch the spider that wriggled and jiggled and tickled inside her.\n")
			} else {
				b.WriteString("She swallowed the " + a.name + " to catch the " + prev.name + ".\n")
			}
		}
		b.WriteString("I don't know why she swallowed the fly. Perhaps she'll die.")
	}
	return b.String()
}
```

Wait — the comment for verse 1 (fly) is empty, so writing comment + "\n" would produce an extra blank line. Let's handle it: if comment is non-empty, write comment + "\n".

For the horse (v=8), the comment is "She's dead, of course!" and there's no chain or final line.

Let's write it cleanly:

```go
package foodchain

import "strings"

var animals = []struct {
	name    string
	comment string
}{
	{"fly", ""},
	{"spider", "It wriggled and jiggled and tickled inside her."},
	{"bird", "How absurd to swallow a bird!"},
	{"cat", "Imagine that, to swallow a cat!"},
	{"dog", "What a hog, to swallow a dog!"},
	{"goat", "Just opened her throat and swallowed a goat!"},
	{"cow", "I don't know how she swallowed a cow!"},
	{"horse", "She's dead, of course!"},
}

func Verse(v int) string {
	var b strings.Builder
	a := animals[v-1]
	b.WriteString("I know an old lady who swallowed a " + a.name + ".\n")
	if a.comment != "" {
		b.WriteString(a.comment + "\n")
	}
	if v < 8 {
		for i := v - 1; i >= 1; i-- {
			prev := animals[i]
			if prev.name == "spider" {
				b.WriteString("She swallowed the " + a.name + " to catch the spider that wriggled and jiggled and tickled inside her.\n")
			} else {
				b.WriteString("She swallowed the " + a.name + " to catch the " + prev.name + ".\n")
			}
		}
		b.WriteString("I don't know why she swallowed the fly. Perhaps she'll die.")
	}
	return b.String()
}

func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, 8)
}
```

